use horus::prelude::*;

struct MotorDriverNode {
    cmd_sub: Topic<CmdVel>,
    left_pwm_pub: Topic<PwmCommand>,
    right_pwm_pub: Topic<PwmCommand>,
    wheel_base: f64,
    wheel_radius: f64,
    max_speed: f64,
}

impl Node for MotorDriverNode {
    fn name(&self) -> &str { "MotorDriver" }

    fn tick(&mut self) {
        if let Some(cmd) = self.cmd_sub.recv() {
            // Convert CmdVel to differential drive
            let diff = DifferentialDriveCommand::from_twist(
                cmd.linear as f64,
                cmd.angular as f64,
                self.wheel_base,
                self.wheel_radius
            );

            // Convert to PWM (-1 to 1)
            let left_duty = (diff.left_velocity / self.max_speed).clamp(-1.0, 1.0) as f32;
            let right_duty = (diff.right_velocity / self.max_speed).clamp(-1.0, 1.0) as f32;

            // Send PWM commands
            self.left_pwm_pub.send(PwmCommand::new(0, left_duty));
            self.right_pwm_pub.send(PwmCommand::new(1, right_duty));
        }
    }
}

pub trait Node: Send {
    // Required
    fn tick(&mut self);

    // Name (defaults to struct type name, e.g. `MotorController`)
    fn name(&self) -> &str { /* derived from type name */ }

    // Optional lifecycle
    fn init(&mut self) -> Result<()> { Ok(()) }
    fn shutdown(&mut self) -> Result<()> { Ok(()) }
    fn on_error(&mut self, error: &str) { hlog!(error, "Node error: {}", error); }

    // Optional metadata
    fn publishers(&self) -> Vec<TopicMetadata> { Vec::new() }
    fn subscribers(&self) -> Vec<TopicMetadata> { Vec::new() }
    fn rate_hz(&self) -> Option<f64> { None }
    fn is_healthy(&self) -> bool { true }

    // Optional checkpoint/restore
    fn checkpoint_state(&self) -> Option<Vec<u8>> { None }
    fn restore_state(&mut self, _data: &[u8]) -> Result<()> { Ok(()) }
    fn supports_checkpointing(&self) -> bool { false }
}

