fn main() -> Result<()> {
    // Configure for production: RT scheduling + flight recorder
    let mut scheduler = Scheduler::new()
        .rt_scheduling(true)
        .with_blackbox(16);

    // Add nodes with execution classes using fluent API
    scheduler.add(EmergencyStop::new()?).order(0).rt().done();
    scheduler.add(MotorController::new()?).order(5).rt().wcet_us(500).done();
    scheduler.add(PathPlanner::new()?).order(10).compute().done();
    scheduler.add(SensorReader::new()?).order(50).rate_hz(1000.0).done();
    scheduler.add(CloudSync::new()?).order(100).async_io().rate_hz(1.0).done();
    scheduler.add(DataLogger::new()?).order(200).rate_hz(10.0).done();

    // Run for 60 seconds
    scheduler.run_for(Duration::from_secs(60))?;

    Ok(())
}

