struct FilterNode {
    raw_sub: Topic<f32>,
    filtered_pub: Topic<f32>,
    alpha: f32,  // Low-pass filter coefficient
    filtered_value: f32,
}

impl FilterNode {
    fn new(alpha: f32) -> Result<Self> {
        Ok(Self {
            raw_sub: Topic::new("raw_data")?,
            filtered_pub: Topic::new("filtered_data")?,
            alpha,
