            let command = if value > self.threshold { 1.0 } else { 0.0 };
            self.cmd_pub.send(command);

            hlog!(info, "Value: {:.2}, Threshold: {:.2}, Command: {:.0}",
                value, self.threshold, command);
        }
    }

    fn shutdown(&mut self) -> Result<()> {
        hlog!(info, "Controller offline");
        Ok(())
    }
}

